'use strict';
const $=s=>document.querySelector(s),canvas=$('#game'),ctx=canvas.getContext('2d');
const cars=[{name:'Alex Team Auto',color:'#d9f877',speed:7,armor:110,weapon:'Formenblaster',rate:.3},{name:'Tesla Roadster',color:'#80c9f2',speed:10,armor:80,weapon:'Elektroblitz',rate:.22},{name:'Iron Buffalo',color:'#ee9d62',speed:5,armor:160,weapon:'Doppelkanone',rate:.6},{name:'Neon Phantom',color:'#cc9cfa',speed:9,armor:90,weapon:'Plasmalaser',rate:.16},{name:'Rally Fox',color:'#f1d47a',speed:8,armor:100,weapon:'Streuschuss',rate:.4}];
const worlds=[{name:'Sunset Canyon',sub:'Wüste · Felsen & Banditen',sky:'#e6a279',mount:'#a45135',ground:'#b56d45',road:'#524c42',tree:'#98502f',length:3000},{name:'Neon City',sub:'Metropole · Drohnen & Barrieren',sky:'#29284b',mount:'#735278',ground:'#232937',road:'#333a50',tree:'#b484df',length:3000},{name:'Frost Valley',sub:'Eiswelt · Glätte & Schneefelsen',sky:'#a2c8d3',mount:'#e6eff0',ground:'#c2d8d8',road:'#6f9098',tree:'#42706c',length:3000},{name:'Jungle Run',sub:'Dschungel · Ruinen & Jäger',sky:'#8caa7a',mount:'#405f44',ground:'#486347',road:'#776d4c',tree:'#253f2e',length:3000}];
let selected=[0,1],modes=['human','ai'],world=0,state='ready',players=[],objects=[],shots=[],particles=[],distance=0,score=0,timer=0,spawn=0,last=0,scroll=0,keys={},sound=false,audio,lastHud=0;
function carSVG(color){return `<svg viewBox="0 0 100 75" class="car-icon" aria-hidden="true"><ellipse cx="50" cy="63" rx="42" ry="7" fill="#0005"/><g transform="translate(7 12)"><path d="M7 22 26 9 62 9 80 25 82 46 4 46Z" fill="${color}"/><path d="m30 13-13 14h49L58 13Z" fill="#283e3f"/><path d="M42 13v14" stroke="${color}" stroke-width="3"/><path d="M5 33h76" stroke="#fff" opacity=".25"/><rect x="10" y="37" width="16" height="20" rx="7" fill="#121814"/><rect x="61" y="37" width="16" height="20" rx="7" fill="#121814"/><circle cx="18" cy="47" r="4" fill="#6a7563"/><circle cx="69" cy="47" r="4" fill="#6a7563"/><path d="M5 31h9m57 0h9" stroke="#fff8c9" stroke-width="4"/></g></svg>`}
function renderPlayers(){ $('#players').innerHTML=selected.map((n,i)=>{let c=cars[n];return `<div class="player"><div class="player-top"><b>SPIELER ${i+1} · ${i?'LINKS':'RECHTS'}</b><select aria-label="Steuerung Spieler ${i+1}" data-mode="${i}"><option value="human" ${modes[i]==='human'?'selected':''}>Spieler</option><option value="ai" ${modes[i]==='ai'?'selected':''}>Computer</option></select></div><div class="vehicle">${carSVG(c.color)}<div><h3>${c.name}</h3><p>${c.weapon}</p></div></div><select class="car-choice" aria-label="Auto Spieler ${i+1}" data-car="${i}">${cars.map((v,j)=>`<option value="${j}" ${j===n?'selected':''}>${v.name}</option>`).join('')}</select><div class="stats"><span>TEMPO <b>${'▰'.repeat(Math.round(c.speed/2))}${'▱'.repeat(5-Math.round(c.speed/2))}</b></span><span>PANZERUNG <b>${c.armor}</b></span></div><div class="keys">${i?'W A S D · Leertaste: Waffe · Q: Form':'↑ ↓ ← → · Enter: Waffe · M: Form'}</div></div>`}).join('');document.querySelectorAll('[data-car]').forEach(e=>e.onchange=()=>{selected[+e.dataset.car]=+e.value;renderPlayers();draw()});document.querySelectorAll('[data-mode]').forEach(e=>e.onchange=()=>modes[+e.dataset.mode]=e.value)}
function renderWorlds(){$('#worlds').innerHTML=worlds.map((w,i)=>`<button class="world ${world===i?'active':''}" data-world="${i}" aria-pressed="${world===i}" style="--sky:${w.sky};--mount:${w.mount}"><span class="num">0${i+1}</span>${world===i?'<span class="check">✓</span>':''}<div class="world-art"></div><div class="world-info"><h3>${w.name}</h3><p>${w.sub}</p></div></button>`).join('');document.querySelectorAll('[data-world]').forEach(e=>e.onclick=()=>{if(state==='running'||state==='paused')return;world=+e.dataset.world;renderWorlds();$('#trackName').textContent=worlds[world].name.toUpperCase();draw()})}
function tone(freq,dur=.08,type='square',vol=.025){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();let o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}catch{}}
function start(){players=selected.map((v,i)=>({x:i?425:575,y:480,hp:cars[v].armor,max:cars[v].armor,car:v,cd:0,inv:0,form:'',formTime:0,formCD:0,ai:modes[i]==='ai',index:i}));objects=[];shots=[];particles=[];distance=0;score=0;timer=0;spawn=.8;scroll=0;state='running';$('#overlay').style.display='none';$('#hud').hidden=false;$('#stageStatus').textContent='TEAM AUF DER STRECKE';setLocked(true);hud();tone(440,.2)}
function setLocked(v){document.querySelectorAll('[data-mode],[data-car],[data-world],#custom').forEach(e=>e.disabled=v)}
function burst(x,y,color,count=12){for(let i=0;i<count;i++)particles.push({x,y,vx:(Math.random()-.5)*230,vy:(Math.random()-.5)*230,life:.6,color})}
function transform(p){if(p.car!==0||p.formCD>0||p.hp<=0)return;const choices=['Drache','Flugzeug','Panzer','Roboter','Geist'];p.form=$('#custom').value.trim()||choices[Math.floor(Math.random()*choices.length)];p.formTime=5;p.formCD=15;p.inv=1;burst(p.x,p.y,'#dcff85',30);tone(780,.3,'sine')}
function fire(p){if(p.cd>0||p.hp<=0)return;let c=cars[p.car];p.cd=c.rate;const add=(dx,vx=0)=>shots.push({x:p.x+dx,y:p.y-30,vx,vy:-600,color:c.color,damage:p.car===2?40:p.car===1?28:20,r:p.car===3?4:6});if(p.car===2){add(-14);add(14)}else if(p.car===4){add(0);add(-12,-110);add(12,110)}else add(0);tone(p.car===1?850:350,.05,'sawtooth')}
function hit(p,damage){if(p.inv>0||p.hp<=0||p.form.toLowerCase().includes('geist'))return;if(p.formTime>0)damage*=.35;p.hp=Math.max(0,p.hp-damage);p.inv=1;burst(p.x,p.y,'#ffab69');tone(95,.15);if(p.hp===0)burst(p.x,p.y,'#ff7760',30)}
function hud(){$('#health').innerHTML=players.map((p,i)=>`<span style="color:${cars[p.car].color}">P${i+1} ${Math.ceil(p.hp)} ♥ ${p.formTime>0?'· '+p.form:p.car===0?'· Form '+(p.formCD>0?Math.ceil(p.formCD)+'s':'bereit'):''}</span>`).join(' &nbsp; ');$('#distance').textContent=`${Math.min(3000,Math.floor(distance))} / 3000 m · ${score} P`}
function end(win){state='ended';setLocked(false);$('#stageStatus').textContent=win?'ZIEL ERREICHT':'NEUER VERSUCH?';$('#hud').hidden=true;$('#overlay').style.display='flex';$('#overlay').innerHTML=`<span class="tiny">${win?'TEAMWORK GEWINNT':'DIE NÄCHSTE RUNDE WARTET'}</span><h2>${win?'Gemeinsam<br>geschafft!':'Team ausgefallen'}</h2><p>${Math.floor(distance)} Meter · ${score} Punkte<br>${win?'Wählt die nächste Welt oder startet erneut.':'Sammelt Reparaturen und deckt euch gegenseitig.'}</p><button id="restart" class="primary">Noch eine Runde ↗</button><small>Autos und Welten sind wieder auswählbar.</small>`;$('#restart').onclick=start;tone(win?660:120,.6,'triangle')}
function pause(){if(state==='running'){state='paused';$('#overlay').style.display='flex';$('#overlay').innerHTML='<span class="tiny">KURZER BOXENSTOPP</span><h2>Pause</h2><button id="resume" class="primary">Weiterfahren ↗</button><button id="quit" style="margin-top:14px;background:none;border:0">Zur Garage</button>';$('#resume').onclick=pause;$('#quit').onclick=()=>end(false)}else if(state==='paused'){state='running';$('#overlay').style.display='none'}}
function update(dt){timer+=dt;distance+=dt*(42+players.reduce((s,p)=>s+(p.hp>0?cars[p.car].speed:0),0)*2);scroll+=dt*200;spawn-=dt;if(spawn<=0){spawn=Math.max(.35,.95-distance/6000);const r=Math.random(),type=r<.13?'heal':r<.26?'energy':r<.61?'rock':'enemy';objects.push({type,x:235+Math.random()*530,y:-50,hp:65,age:0,cd:1+Math.random(),speed:type==='enemy'?70:0,seed:Math.random()*10})}
for(const p of players){p.cd=Math.max(0,p.cd-dt);p.inv=Math.max(0,p.inv-dt);p.formCD=Math.max(0,p.formCD-dt);p.formTime=Math.max(0,p.formTime-dt);if(!p.formTime)p.form='';if(p.hp<=0)continue;let dx=0,dy=0;const speed=140+cars[p.car].speed*15;if(p.ai){let target=p.index?390:610;let danger=objects.filter(o=>(o.type==='rock'||o.type==='enemy'||o.type==='bullet')&&o.y>p.y-190&&o.y<p.y+45&&Math.abs(o.x-p.x)<90).sort((a,b)=>b.y-a.y)[0];let heal=objects.find(o=>o.type==='heal'&&o.y>p.y-200&&o.y<p.y&&p.hp<p.max*.7);if(danger)target=p.x+(danger.x<p.x?150:-150);else if(heal)target=heal.x;dx=Math.max(-1,Math.min(1,(target-p.x)/40));fire(p);if(danger)transform(p)}else{if(p.index===0){dx=(keys.ArrowRight?1:0)-(keys.ArrowLeft?1:0);dy=(keys.ArrowDown?1:0)-(keys.ArrowUp?1:0);if(keys.Enter)fire(p);if(keys.KeyM)transform(p)}else{dx=(keys.KeyD?1:0)-(keys.KeyA?1:0);dy=(keys.KeyS?1:0)-(keys.KeyW?1:0);if(keys.Space)fire(p);if(keys.KeyQ)transform(p)}}p.x=Math.max(225,Math.min(775,p.x+dx*speed*dt));p.y=Math.max(150,Math.min(570,p.y+dy*speed*dt))}
for(const o of objects){o.age+=dt;o.y+=(200-o.speed)*dt;if(o.type==='enemy'){o.x+=Math.sin(o.age*2+o.seed)*25*dt;o.cd-=dt;if(o.cd<=0){o.cd=1.6;objects.push({type:'bullet',x:o.x,y:o.y+35,speed:-100,age:0})}}for(const p of players){if(Math.abs(o.x-p.x)<(o.type==='bullet'?24:37)&&Math.abs(o.y-p.y)<40){if(o.type==='heal'){players.forEach(v=>v.hp=Math.min(v.max,v.hp+35));o.dead=true;burst(o.x,o.y,'#a6f890');score+=50;tone(880,.15,'sine');break}if(p.hp<=0)continue;if(o.type==='energy'){score+=100;o.dead=true;burst(o.x,o.y,'#ffe292');tone(1100,.1);break}let flying=/flug|drache|raumschiff|vogel/i.test(p.form);if(o.type==='rock'&&flying)continue;hit(p,o.type==='bullet'?10:22);if(o.type==='bullet')o.dead=true}}}
for(const s of shots){s.x+=s.vx*dt;s.y+=s.vy*dt;for(const o of objects){if((o.type==='rock'||o.type==='enemy')&&!o.dead&&Math.abs(o.x-s.x)<32&&Math.abs(o.y-s.y)<35){o.hp-=s.damage;s.dead=true;burst(s.x,s.y,s.color,3);if(o.hp<=0){o.dead=true;score+=o.type==='enemy'?150:30;burst(o.x,o.y,'#ffbb79',20);tone(130,.09)}break}}}
objects=objects.filter(o=>!o.dead&&o.y<700);shots=shots.filter(s=>!s.dead&&s.y>-40&&s.x>0&&s.x<1000);for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);lastHud+=dt;if(lastHud>.1){hud();lastHud=0}if(players.every(p=>p.hp<=0))end(false);else if(distance>=3000)end(true)}
function poly(points,fill){ctx.fillStyle=fill;ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fill()}
function drawCar(x,y,color,enemy=false,form='',alpha=1){ctx.save();ctx.translate(x,y);ctx.globalAlpha=alpha;if(enemy)ctx.rotate(Math.PI);if(form){ctx.shadowColor=color;ctx.shadowBlur=25;ctx.fillStyle=color+'33';ctx.beginPath();ctx.ellipse(0,0,48,56,0,0,7);ctx.fill();ctx.shadowBlur=0;if(/flug|drache|vogel|raumschiff/i.test(form)){poly([[-12,-12],[-65,22],[-62,31],[0,12],[62,31],[65,22],[12,-12]],color)}if(/panzer|roboter/i.test(form)){ctx.fillStyle='#202824';ctx.fillRect(-34,-33,18,68);ctx.fillRect(16,-33,18,68)}}ctx.fillStyle='#0005';ctx.beginPath();ctx.ellipse(4,9,27,43,0,0,7);ctx.fill();ctx.fillStyle='#1c201c';ctx.fillRect(-26,-24,10,19);ctx.fillRect(16,-24,10,19);ctx.fillRect(-26,16,10,19);ctx.fillRect(16,16,10,19);ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(-20,-39,40,78,[12,12,7,7]);ctx.fill();ctx.fillStyle='#263f42';poly([[-15,-15],[-12,-26],[12,-26],[15,-15]],'#203b3f');poly([[-14,14],[-11,24],[11,24],[14,14]],'#263e3c');ctx.fillStyle='#ffffff25';ctx.fillRect(-14,-10,28,20);ctx.fillStyle='#fff4bb';ctx.fillRect(-17,-34,9,5);ctx.fillRect(8,-34,9,5);ctx.fillStyle='#ed6b53';ctx.fillRect(-17,31,8,4);ctx.fillRect(9,31,8,4);ctx.fillStyle='#ffffff50';ctx.fillRect(-2,-37,4,14);ctx.restore()}
function draw(){const w=worlds[world];ctx.clearRect(0,0,1000,620);ctx.fillStyle=w.ground;ctx.fillRect(0,0,1000,620);let off=scroll%160;for(let i=-1;i<5;i++){let y=i*160+off;for(const x of [55,890]){if(world===1){ctx.fillStyle=i%2?'#394453':'#454451';ctx.fillRect(x-30,y-80,85,130);ctx.fillStyle='#a6d3d8';for(let k=0;k<3;k++)ctx.fillRect(x-20+k*23,y-60,7,30)}else if(world===3){ctx.fillStyle=w.tree;for(let k=0;k<3;k++){ctx.beginPath();ctx.arc(x+k*15,y-k*17,28,0,7);ctx.fill()}}else{poly([[x-30,y+25],[x-20,y-15],[x+20,y-28],[x+48,y+15],[x+20,y+39]],w.tree);poly([[x-20,y-15],[x+20,y-28],[x+8,y+8]],world===2?'#eff8ef':'#c28252')}}}ctx.fillStyle=w.road;ctx.fillRect(205,0,590,620);ctx.fillStyle='#272c2944';ctx.fillRect(220,0,560,620);ctx.fillStyle=world===1?'#b596cf':'#e5c99b';ctx.fillRect(201,0,6,620);ctx.fillRect(793,0,6,620);ctx.fillStyle='#dfdbba55';for(let j=-1;j<8;j++){let y=j*100+scroll%100;ctx.fillRect(397,y,4,46);ctx.fillRect(599,y,4,46)}for(let j=-1;j<18;j++){let y=j*40+scroll%40;ctx.fillStyle=j%2===0?'#ece1be':'#9f503d';ctx.fillRect(188,y,12,38);ctx.fillRect(800,y,12,38)}
if(state==='ready'){for(let i=0;i<4;i++){ctx.fillStyle='#b97c4c';ctx.fillRect(250+i*150,85,65,20)}drawCar(425,485,cars[selected[1]].color);drawCar(575,450,cars[selected[0]].color);drawCar(520,90,'#c46a55',true);ctx.strokeStyle='#ead5b944';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(425,550);ctx.lineTo(425,620);ctx.moveTo(575,515);ctx.lineTo(575,620);ctx.stroke()}
if(distance>2700){let y=-100+(distance-2700)*2.2;for(let i=0;i<15;i++)for(let j=0;j<2;j++){ctx.fillStyle=(i+j)%2?'#252d25':'#f1ead1';ctx.fillRect(205+i*39.4,y+j*20,40,20)}}
for(const o of objects){if(o.type==='enemy')drawCar(o.x,o.y,'#de795f',true);else if(o.type==='rock'){poly([[o.x-30,o.y+17],[o.x-25,o.y-18],[o.x+3,o.y-30],[o.x+30,o.y-10],[o.x+27,o.y+24],[o.x-4,o.y+30]],world===2?'#cadfe3':'#9b8166');poly([[o.x-25,o.y-18],[o.x+3,o.y-30],[o.x+6,o.y]],world===2?'#edf5f5':'#c5a080')}else if(o.type==='bullet'){ctx.fillStyle='#ff9c70';ctx.fillRect(o.x-4,o.y-9,8,18)}else{ctx.save();ctx.translate(o.x,o.y);ctx.rotate(Math.sin(timer*3)*.15);ctx.fillStyle=o.type==='heal'?'#c2f797':'#f6d875';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=15;ctx.beginPath();ctx.roundRect(-15,-15,30,30,6);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#294a28';ctx.font='bold 25px Arial';ctx.textAlign='center';ctx.fillText(o.type==='heal'?'+':'ϟ',0,9);ctx.restore()}}
for(const s of shots){ctx.fillStyle=s.color;ctx.shadowBlur=10;ctx.shadowColor=s.color;ctx.fillRect(s.x-s.r/2,s.y-12,s.r,25);ctx.shadowBlur=0}for(const p of players){if(p.hp<=0){ctx.fillStyle='#171b17';ctx.fillRect(p.x-20,p.y-30,40,60);continue}drawCar(p.x,p.y,cars[p.car].color,false,p.form,p.inv>0&&Math.floor(timer*14)%2?.45:1);ctx.textAlign='center';ctx.font='bold 11px Arial';ctx.fillStyle=cars[p.car].color;ctx.fillText(p.form||`P${p.index+1}${p.ai?' · CPU':''}`,p.x,p.y+60);ctx.fillStyle='#172216';ctx.fillRect(p.x-23,p.y+44,46,4);ctx.fillStyle=cars[p.car].color;ctx.fillRect(p.x-23,p.y+44,46*p.hp/p.max,4)}for(const p of particles){ctx.globalAlpha=p.life/.6;ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,5,5)}ctx.globalAlpha=1;let shade=ctx.createLinearGradient(0,0,1000,0);shade.addColorStop(0,'#28191455');shade.addColorStop(.4,'#0000');shade.addColorStop(1,'#28191444');ctx.fillStyle=shade;ctx.fillRect(0,0,1000,620)}
function loop(t){let dt=Math.min((t-last)/1000,.04);last=t;if(state==='running')update(dt);draw();requestAnimationFrame(loop)}
window.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','Enter'].includes(e.code))e.preventDefault();keys[e.code]=true;if(!e.repeat&&(e.code==='KeyP'||e.code==='Escape'))pause()});window.addEventListener('keyup',e=>keys[e.code]=false);window.addEventListener('blur',()=>{keys={};if(state==='running')pause()});$('#start').onclick=start;$('#pause').onclick=pause;$('#help').onclick=()=>{if(state==='running')pause();$('#instructions').showModal()};$('#closeHelp').onclick=()=>$('#instructions').close();$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent=sound?'♪ Sound an':'♪ Sound aus';tone(550)};renderPlayers();renderWorlds();requestAnimationFrame(loop);
